export interface NpcPlacement { actor: string; at: Point; ambient: Localized; companionAfter?: string; activity?: 'work' | 'walk' | 'rest' }
export interface Objective {
  id: string;
  kind: 'talk' | 'inspect' | 'reach' | 'drive' | 'chase' | 'fight' | 'deduce' | 'travel' | 'finish';
  title: Localized;
  detail: Localized;
  at: Point;
  actor?: string;
  lines?: Localized[];
  evidence?: { title: Localized; body: Localized };
  choices?: { label: Localized; correct: boolean }[];
  stealth?: boolean;
  seconds?: number;
}

export interface RegionDefinition {
  id: string;
  chapter: number;
  part?: string;
  title: Localized;
  place: Localized;
  country: Localized;
  biome: Biome;
  image: string;
  intro: Localized;
  outro: Localized;
  map: Point;
  day: number;
  span: number;
  weather: Weather;
  night?: boolean;
  returning?: boolean;
  vehicle?: Point;
  npcs: NpcPlacement[];
  objectives: Objective[];
  enemies?: { at: Point; hp: number; from: number; boss?: boolean }[];
}

const talkHint = L('اقترب من الشخصية واضغط E. يمكنك قراءة الحوار على مهل.', 'Approach and press E. Take your time with the conversation.', 'Approchez et appuyez sur E. Prenez le temps de lire.');
const inspectHint = L('اتبع العلامة الذهبية ثم اضغط E لفحص الدليل.', 'Follow the gold marker, then press E to examine the evidence.', 'Suivez le repère doré puis appuyez sur E pour examiner l’indice.');
const walkHint = L('استكشف الطريق واتبع العلامة. Shift للركض وSpace للقفز.', 'Explore the path. Shift to sprint, Space to jump.', 'Explorez le chemin. Maj pour courir, Espace pour sauter.');
const driveHint = L('اركب مركبة أسفار بـE. W/S للتسارع والرجوع، A/D للتوجيه وSpace للفرملة.', 'Enter the Asfar rover with E. W/S accelerate or reverse, A/D steer, Space brakes.', 'Montez dans Asfar avec E. W/S accélèrent ou reculent, A/D dirigent, Espace freine.');
const travelHint = L('اذهب إلى علامة الطريق واضغط E لبدء المرحلة التالية.', 'Reach the route marker and press E to continue the journey.', 'Rejoignez le repère et appuyez sur E pour poursuivre le voyage.');
const alg = L('الجزائر', 'Algeria', 'Algérie');
const taz = L('تازيرا / دولة خيالية', 'Tazira / fictional country', 'Tazira / pays fictif');

function talk(id: string, actor: string, at: Point, title: Localized, lines: Localized[]): Objective { return { id, actor, at, title, lines, kind: 'talk', detail: talkHint }; }
function inspect(id: string, at: Point, title: Localized, body: Localized, stealth = false): Objective { return { id, at, title, kind: 'inspect', detail: stealth ? L('انحنِ بـC أو زر الانحناء وافحص الأرشيف بـE. استعمل الجدران ساترًا.', 'Crouch with C, then inspect with E. Use the walls as cover.', 'Accroupissez-vous avec C, puis examinez avec E. Utilisez les murs comme abri.') : inspectHint, evidence: { title, body }, lines: [body], stealth }; }
function reach(id: string, at: Point, title: Localized, kind: 'reach' | 'drive' | 'chase' = 'reach'): Objective { return { id, at, title, kind, detail: kind === 'drive' ? driveHint : kind === 'chase' ? L('اركض إلى الكهف قبل انقضاء الوقت. احتمِ بالصخور من طائرات الظل.', 'Sprint to the cave before time runs out. Break drone fire with the rocks.', 'Courez vers la grotte avant la fin du temps. Abritez-vous derrière les rochers.' ) : walkHint, seconds: kind === 'chase' ? 65 : undefined }; }
function leave(id: string, at: Point, title: Localized): Objective { return { id, at, title, kind: 'travel', detail: travelHint }; }
function deduce(id: string, at: Point, title: Localized, body: Localized, choices: Localized[], answer: number): Objective {
  const conclusion = L(`${body.ar}\nالاستنتاج الموثق: ${choices[answer].ar}.`, `${body.en}\nRecorded conclusion: ${choices[answer].en}.`, `${body.fr}\nConclusion consignée : ${choices[answer].fr}.`);
  return { id, at, title, kind: 'deduce', detail: L('افتح لوحة الأدلة بـE واربط الشهادات. الإجابة الخاطئة لا تفقدك التقدم.', 'Open the evidence board with E and connect the testimonies. A wrong answer never erases progress.', 'Ouvrez le tableau avec E et reliez les témoignages. Une erreur n’efface pas votre progression.'), lines: [body], evidence: { title, body: conclusion }, choices: choices.map((label, i) => ({ label, correct: i === answer })) };
}

