export const defaultJourney = (): JourneyProgress => ({ region: 0, step: 0, completed: [], visited: [0], met: [], evidence: [], souvenirs: [], finished: false, elapsed: 0, chaseRemaining: 0 });

export function validJourneySave(value: unknown): value is SavedRun {
  if (!value || typeof value !== 'object') return false;
  const run = value as SavedRun;
  const j = run.journey;
  const point = (v: unknown): boolean => Array.isArray(v) && v.length === 3 && v.every(n => typeof n === 'number' && Number.isFinite(n));
  const strings = (v: unknown): boolean => Array.isArray(v) && v.every(item => typeof item === 'string');
  return run.version === 2 && !!j && Number.isInteger(j.region) && j.region >= 0 && j.region < CAMPAIGN.length
    && Number.isInteger(j.step) && j.step >= 0 && j.step <= CAMPAIGN[j.region].objectives.length
    && strings(j.completed) && Array.isArray(j.visited) && j.visited.every(n => Number.isInteger(n) && n >= 0 && n < CAMPAIGN.length)
    && strings(j.met) && strings(j.evidence) && strings(j.souvenirs) && typeof j.finished === 'boolean'
    && point(run.position) && Number.isFinite(run.yaw)
    && Number.isFinite(run.health) && run.health > 0 && Number.isFinite(run.score) && Number.isFinite(run.xp)
    && Number.isFinite(j.elapsed) && Number.isFinite(j.chaseRemaining) && Number.isFinite(run.kills) && Number.isFinite(run.bestCombo)
    && Number.isFinite(run.ammo) && (run.weapon === 'azru' || run.weapon === 'sirocco')
    && Array.isArray(run.enemies) && run.enemies.every(Number.isFinite) && Array.isArray(run.targets) && run.targets.every(Number.isFinite) && Array.isArray(run.relics)
    && (!j.vehicle || (point(j.vehicle.position) && Number.isFinite(j.vehicle.yaw) && Number.isFinite(j.vehicle.integrity) && typeof j.vehicle.driving === 'boolean'))
    && (!j.trail || (Array.isArray(j.trail) && j.trail.every(point)))
    && (!j.companions || (typeof j.companions === 'object' && Object.values(j.companions).every(c => c && point(c.position) && Number.isInteger(c.trail) && c.trail >= 0)));
}

export function validateCampaign() {
  const ids = new Set<string>();
  for (const region of CAMPAIGN) {
    const exit = region.objectives[region.objectives.length - 1];
    if (exit?.kind !== 'travel' && exit?.kind !== 'finish') throw new Error(`Missing chapter exit: ${region.id}`);
    for (const npc of region.npcs) {
      if (!ACTORS[npc.actor]) throw new Error(`Unknown actor: ${npc.actor}`);
      if (npc.companionAfter && !region.objectives.some(o => o.id === npc.companionAfter)) throw new Error(`Invalid companion introduction: ${npc.actor}`);
    }
    for (const objective of region.objectives) {
      if (ids.has(objective.id)) throw new Error(`Duplicate objective: ${objective.id}`);
      ids.add(objective.id);
      if (objective.actor && !region.npcs.some(n => n.actor === objective.actor)) throw new Error(`Missing NPC: ${objective.id}`);
      if (objective.choices && objective.choices.filter(c => c.correct).length !== 1) throw new Error(`Invalid deduction: ${objective.id}`);
      if (!objective.at.every(Number.isFinite) || objective.at[1] < 26 - region.span || objective.at[1] > 27) throw new Error(`Objective outside the playable region: ${objective.id}`);
      if (objective.kind === 'drive' && !region.vehicle) throw new Error(`Missing mission vehicle: ${objective.id}`);
      if (objective.kind === 'talk' && !objective.lines?.length) throw new Error(`Missing story conversation: ${objective.id}`);
      for (const language of ['ar', 'en', 'fr'] as const) if (!objective.title[language] || !objective.detail[language]) throw new Error(`Missing ${language} objective translation: ${objective.id}`);
    }
  }
  if (new Set(CAMPAIGN.map(r => r.chapter)).size !== 12) throw new Error('The campaign must contain twelve connected chapters.');
  if (CAMPAIGN.length !== 14) throw new Error('The journey must contain fourteen regional stops.');
}